def comps(a,val):
 h,w=a.shape; seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   if a[r,c]!=val or (r,c) in seen: continue
   q=[(r,c)];seen.add((r,c));co=[]
   while q:
    x,y=q.pop();co.append((x,y))
    for z in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
     if 0<=z[0]<h and 0<=z[1]<w and a[z]!=val and z not in seen: seen.add(z);q.append(z)
   out.append(co)
 return out
